use atlas_native_storage_contract::{create_workspace,add_file,object_revision,file_revision};
use std::{fs,io::Write,path::PathBuf,process::{Command,Stdio},time::{SystemTime,UNIX_EPOCH}};
#[test]fn revision_matches_python_json_and_raw_bytes(){let p=std::env::temp_dir().join(format!("atlas-revision-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));create_workspace(&p).unwrap();let bytes=b"payload\x00bytes";let id=add_file(&p,"тест.txt",bytes).unwrap();let prefix=format!("[\"{}\", \"file\", \"тест.txt\", \"\"]",id);let mut child=Command::new("/usr/bin/openssl").args(["dgst","-sha256"]).stdin(Stdio::piped()).stdout(Stdio::piped()).spawn().unwrap();{let s=child.stdin.as_mut().unwrap();s.write_all(prefix.as_bytes()).unwrap();s.write_all(bytes).unwrap();}let output=child.wait_with_output().unwrap();let expected=String::from_utf8(output.stdout).unwrap().split_whitespace().last().unwrap().to_string();assert_eq!(object_revision(&p,&id).unwrap(),expected);assert_eq!(file_revision(&p,&id).unwrap(),expected);fs::remove_dir_all(p).unwrap();}
